ohm_required_drive(desired_flow, resistance)

// Exact declared simple-cycle gain: 0.5 * 0.5 = 1/4.
// This static path calculation is not a dynamical or empirical stability claim.
circuit bounded_feedback {
    input: prompt;
    output: response;
    node question: ^8^C_{F2}|A;
    node bias: ^5^C_{F2}|A;
    node answer: ^9^C_{F6}|A;
    cjt decision: CJT< question | bias => answer > [beta=0.5, gm=0.1];
    feedback return_path: answer -> question [beta=0.5];
    probe tp_answer: answer;
}

// A declared layout and one downward via, not an executed circuit.
// Inline via endpoints retain their own identities; no named-node join is inferred.
board downward_layout {
    layer P: [ charter: ^5^P_{F7}|T ];
    layer C: [ understand: ^1^C_{F2}|A ];
    via intake: ^5^P -> ^1^C;
}

// Authored structural example; execution and measured cognition are unavailable.
// I/O terminals are declared but untyped and deliberately unconnected.
// The checker must warn about them; it must not invent prompt-to-response wiring.
circuit guarded_chain {
    input: prompt;
    output: response;
    node question: ^8^C_{F2}|A;
    node charter: ^5^P_{F7}|T;
    node answer: ^9^C_{F6}|A;
    cjt decision: CJT< question | charter => answer > [beta=0.5, gm=0.1, sat=0.95, cutoff=0.1];
    resistor restraint: Resistor< question, R=30 >;
    capacitor memory: Capacitor< charter, C=10, leakage=0.01 >;
    inductor habit: Inductor< answer, L=1 >;
    probe tp_answer: answer;
}

// Topological evaluation must run z_first before a_second despite their names.
board cascade {
    input: stimulus;
    output: answer;
    node cause: ^8^C_{F2}|A;
    node bias: ^5^P_{F7}|T;
    node middle: ^9^C_{F6}|A;
    node effect: ^9^C_{F6}|A;
    cjt a_second: CJT< middle | bias => effect > [beta=0.5, sat=0.9, cutoff=0.1];
    cjt z_first: CJT< cause | bias => middle > [beta=2, sat=0.75, cutoff=0.1];
    probe observed: effect;
}

// Scalar design simulation; values are declared activations, not measurements.
board fixed_bias {
    input: drive;
    output: response;
    node cause: ^8^C_{F2}|A;
    node bias: ^5^P_{F7}|T;
    node effect: ^9^C_{F6}|A;
    cjt stage: CJT< cause | bias => effect > [beta=2, sat=0.85, cutoff=0.1];
    probe observed: effect;
}

// The two named nets remain independent even though their state types match.
circuit ohm_independent {
    input: supply_a, supply_b;
    output: flow_a, flow_b;
    node rail_a: ^8^C_{F5}|A;
    node rail_b: ^8^C_{F5}|A;
    resistor r_b: Resistor< rail_b, R=3 >;
    resistor r_a: Resistor< rail_a, R=30 >;
    probe tp_a: rail_a;
    probe tp_b: rail_b;
}

// Runtime routing is explicit in ohm_resistor.inputs.json.
// Drive and attention have distinct declared quantity kinds on this net.
circuit ohm_resistor {
    input: supply;
    output: flow;
    node rail: ^8^C_{F5}|A;
    resistor r1: Resistor< rail, R=30 >;
    probe tp_flow: rail;
}
